package ru.projectkingdom.npc;import net.minecraft.core.*;import net.minecraft.server.level.*;import net.minecraft.world.*;public class KingdomContainerAccess{public static Container resolve(ServerLevel level,BlockPos pos){return level.containers.get(pos);}public static boolean samePhysicalStorage(ServerLevel level,BlockPos a,BlockPos b){return level.containers.containsKey(a)&&level.containers.get(a)==level.containers.get(b);}}
